    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def sep(g):
    H=len(g);W=len(g[0]);seps=[]
    for r in range(H):
        v=g[r][0]
        if len(set(g[r]))==1 and sum(1 for rr in range(H) for cc in range(W) if g[rr][cc]==v)==W: seps.append(('row',r))
    for c in range(W):
        v=g[0][c]
        if len({g[rr][c] for rr in range(H)})==1 and sum(1 for rr in range(H) for cc in range(W) if g[rr][cc]==v)==H: seps.append(('col',c))
    return seps[0]
