    ca={x for row in A for x in row}; cb={x for row in B for x in row}
    common=ca&cb
    fill=common.pop() if len(common)==1 else None
    h,w=len(A),len(A[0])
    out=[[fill]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if A[i][j]==B[i][j]: out[i][j]=3
